#!/usr/bin/env python3\n\"\"\"\nPerformance Monitor for Air-Gapped RAG System\nCollects and analyzes performance metrics across all components\n\"\"\"\n\nimport os\nimport sys\nimport time\nimport json\nimport logging\nimport argparse\nimport statistics\nfrom datetime import datetime, timedelta\nfrom typing import Dict, List, Any, Optional\nfrom dataclasses import dataclass, asdict\n\nimport boto3\nimport requests\nfrom botocore.exceptions import ClientError\n\n# Add src directory to path\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'src'))\n\nfrom ai_inference.core.config import get_config\n\n@dataclass\nclass PerformanceMetrics:\n    \"\"\"Performance metrics data structure.\"\"\"\n    timestamp: str\n    environment: str\n    \n    # Queue Metrics\n    queue_depth: int\n    messages_in_flight: int\n    dlq_depth: int\n    message_age_seconds: float\n    \n    # Processing Metrics\n    processing_rate_per_minute: float\n    error_rate_percent: float\n    average_processing_time_ms: float\n    \n    # Infrastructure Metrics\n    vllm_response_time_ms: float\n    vllm_availability_percent: float\n    worker_uptime_seconds: int\n    \n    # Resource Metrics\n    cpu_usage_percent: float\n    memory_usage_percent: float\n    disk_usage_percent: float\n    \n    # Network Metrics\n    vpn_status: str\n    aws_connectivity: bool\n    network_latency_ms: float\n\nclass PerformanceMonitor:\n    \"\"\"Monitors and analyzes system performance.\"\"\"\n    \n    def __init__(self, environment: str = \"dev\"):\n        self.config = get_config(environment)\n        self.environment = environment\n        self.logger = self._setup_logging()\n        \n        # AWS clients\n        self.session = boto3.Session(region_name=self.config.aws_region)\n        self.cloudwatch = self.session.client(\"cloudwatch\")\n        self.sqs = self.session.client(\"sqs\")\n        self.ssm = self.session.client(\"ssm\")\n    \n    def _setup_logging(self) -> logging.Logger:\n        \"\"\"Setup logging.\"\"\"\n        logger = logging.getLogger(\"RAG-PerformanceMonitor\")\n        logger.setLevel(logging.INFO)\n        \n        formatter = logging.Formatter('%(asctime)s [%(levelname)s] %(name)s: %(message)s')\n        handler = logging.StreamHandler()\n        handler.setFormatter(formatter)\n        logger.addHandler(handler)\n        \n        return logger\n    \n    def collect_queue_metrics(self) -> Dict[str, Any]:\n        \"\"\"Collect SQS queue metrics.\"\"\"\n        try:\n            # Main queue metrics\n            queue_attrs = self.sqs.get_queue_attributes(\n                QueueUrl=self.config.queue_url,\n                AttributeNames=[\n                    'ApproximateNumberOfMessages',\n                    'ApproximateNumberOfMessagesNotVisible',\n                    'ApproximateAgeOfOldestMessage'\n                ]\n            )['Attributes']\n            \n            # DLQ metrics\n            dlq_attrs = self.sqs.get_queue_attributes(\n                QueueUrl=self.config.dlq_url,\n                AttributeNames=['ApproximateNumberOfMessages']\n            )['Attributes']\n            \n            return {\n                'queue_depth': int(queue_attrs.get('ApproximateNumberOfMessages', 0)),\n                'messages_in_flight': int(queue_attrs.get('ApproximateNumberOfMessagesNotVisible', 0)),\n                'dlq_depth': int(dlq_attrs.get('ApproximateNumberOfMessages', 0)),\n                'message_age_seconds': float(queue_attrs.get('ApproximateAgeOfOldestMessage', 0))\n            }\n        except Exception as e:\n            self.logger.error(f\"Failed to collect queue metrics: {e}\")\n            return {\n                'queue_depth': -1,\n                'messages_in_flight': -1,\n                'dlq_depth': -1,\n                'message_age_seconds': -1\n            }\n    \n    def collect_processing_metrics(self) -> Dict[str, Any]:\n        \"\"\"Collect processing performance metrics from CloudWatch.\"\"\"\n        try:\n            end_time = datetime.utcnow()\n            start_time = end_time - timedelta(minutes=5)\n            \n            # Processing rate\n            processing_rate = self._get_cloudwatch_metric(\n                'AWS/SQS', 'NumberOfMessagesDeleted',\n                {'QueueName': self.config.queue_name},\n                start_time, end_time, 'Sum'\n            )\n            \n            # Error metrics\n            errors = self._get_cloudwatch_metric(\n                'AirGappedRAG', 'ProcessingErrors',\n                {'Environment': self.environment},\n                start_time, end_time, 'Sum'\n            )\n            \n            successes = self._get_cloudwatch_metric(\n                'AirGappedRAG', 'ProcessingSuccesses',\n                {'Environment': self.environment},\n                start_time, end_time, 'Sum'\n            )\n            \n            # Calculate error rate\n            total_processed = (errors or 0) + (successes or 0)\n            error_rate = (errors / total_processed * 100) if total_processed > 0 else 0\n            \n            # Processing time\n            avg_processing_time = self._get_cloudwatch_metric(\n                'AirGappedRAG', 'ProcessingTime',\n                {'Environment': self.environment},\n                start_time, end_time, 'Average'\n            )\n            \n            return {\n                'processing_rate_per_minute': (processing_rate or 0) / 5,  # Convert to per minute\n                'error_rate_percent': error_rate,\n                'average_processing_time_ms': avg_processing_time or 0\n            }\n        except Exception as e:\n            self.logger.error(f\"Failed to collect processing metrics: {e}\")\n            return {\n                'processing_rate_per_minute': -1,\n                'error_rate_percent': -1,\n                'average_processing_time_ms': -1\n            }\n    \n    def collect_infrastructure_metrics(self) -> Dict[str, Any]:\n        \"\"\"Collect infrastructure metrics.\"\"\"\n        try:\n            # vLLM metrics\n            vllm_response_time, vllm_available = self._test_vllm_performance()\n            \n            # Worker uptime\n            worker_uptime = self._get_worker_uptime()\n            \n            return {\n                'vllm_response_time_ms': vllm_response_time,\n                'vllm_availability_percent': 100.0 if vllm_available else 0.0,\n                'worker_uptime_seconds': worker_uptime\n            }\n        except Exception as e:\n            self.logger.error(f\"Failed to collect infrastructure metrics: {e}\")\n            return {\n                'vllm_response_time_ms': -1,\n                'vllm_availability_percent': 0,\n                'worker_uptime_seconds': -1\n            }\n    \n    def collect_resource_metrics(self) -> Dict[str, Any]:\n        \"\"\"Collect system resource metrics.\"\"\"\n        try:\n            import psutil\n            \n            return {\n                'cpu_usage_percent': psutil.cpu_percent(interval=1),\n                'memory_usage_percent': psutil.virtual_memory().percent,\n                'disk_usage_percent': psutil.disk_usage('/').percent\n            }\n        except ImportError:\n            self.logger.warning(\"psutil not available, using system commands\")\n            return self._collect_resource_metrics_fallback()\n        except Exception as e:\n            self.logger.error(f\"Failed to collect resource metrics: {e}\")\n            return {\n                'cpu_usage_percent': -1,\n                'memory_usage_percent': -1,\n                'disk_usage_percent': -1\n            }\n    \n    def collect_network_metrics(self) -> Dict[str, Any]:\n        \"\"\"Collect network and connectivity metrics.\"\"\"\n        try:\n            # VPN status\n            vpn_status = self._check_vpn_status()\n            \n            # AWS connectivity\n            aws_connectivity = self._test_aws_connectivity()\n            \n            # Network latency\n            network_latency = self._measure_network_latency()\n            \n            return {\n                'vpn_status': vpn_status,\n                'aws_connectivity': aws_connectivity,\n                'network_latency_ms': network_latency\n            }\n        except Exception as e:\n            self.logger.error(f\"Failed to collect network metrics: {e}\")\n            return {\n                'vpn_status': 'unknown',\n                'aws_connectivity': False,\n                'network_latency_ms': -1\n            }\n    \n    def _get_cloudwatch_metric(self, namespace: str, metric_name: str, \n                              dimensions: Dict[str, str], start_time: datetime, \n                              end_time: datetime, statistic: str) -> Optional[float]:\n        \"\"\"Get CloudWatch metric value.\"\"\"\n        try:\n            response = self.cloudwatch.get_metric_statistics(\n                Namespace=namespace,\n                MetricName=metric_name,\n                Dimensions=[{'Name': k, 'Value': v} for k, v in dimensions.items()],\n                StartTime=start_time,\n                EndTime=end_time,\n                Period=300,\n                Statistics=[statistic]\n            )\n            \n            if response['Datapoints']:\n                return response['Datapoints'][-1][statistic]\n            return None\n        except Exception:\n            return None\n    \n    def _test_vllm_performance(self) -> tuple[float, bool]:\n        \"\"\"Test vLLM server performance.\"\"\"\n        try:\n            start_time = time.time()\n            response = requests.get(\n                f\"{self.config.vllm_url}/v1/models\",\n                timeout=10\n            )\n            response_time = (time.time() - start_time) * 1000\n            \n            return response_time, response.status_code == 200\n        except Exception:\n            return -1, False\n    \n    def _get_worker_uptime(self) -> int:\n        \"\"\"Get worker service uptime in seconds.\"\"\"\n        try:\n            import subprocess\n            result = subprocess.run(\n                ['systemctl', 'show', 'rag-worker', '--property=ActiveEnterTimestamp'],\n                capture_output=True, text=True\n            )\n            \n            if result.returncode == 0:\n                timestamp_line = result.stdout.strip()\n                if 'ActiveEnterTimestamp=' in timestamp_line:\n                    timestamp_str = timestamp_line.split('=', 1)[1]\n                    if timestamp_str and timestamp_str != 'n/a':\n                        # Parse systemd timestamp and calculate uptime\n                        # This is a simplified version - full implementation would parse the timestamp\n                        return 3600  # Placeholder - return 1 hour\n            return -1\n        except Exception:\n            return -1\n    \n    def _collect_resource_metrics_fallback(self) -> Dict[str, Any]:\n        \"\"\"Fallback method for collecting resource metrics using system commands.\"\"\"\n        try:\n            import subprocess\n            \n            # CPU usage\n            cpu_result = subprocess.run(\n                ['top', '-bn1'], capture_output=True, text=True\n            )\n            cpu_usage = -1\n            for line in cpu_result.stdout.split('\\n'):\n                if 'Cpu(s):' in line:\n                    # Parse CPU usage from top output\n                    parts = line.split()\n                    for i, part in enumerate(parts):\n                        if '%us' in part:\n                            cpu_usage = float(parts[i-1])\n                            break\n            \n            # Memory usage\n            mem_result = subprocess.run(\n                ['free'], capture_output=True, text=True\n            )\n            memory_usage = -1\n            for line in mem_result.stdout.split('\\n'):\n                if 'Mem:' in line:\n                    parts = line.split()\n                    total = int(parts[1])\n                    used = int(parts[2])\n                    memory_usage = (used / total) * 100\n                    break\n            \n            # Disk usage\n            disk_result = subprocess.run(\n                ['df', '-h', '/'], capture_output=True, text=True\n            )\n            disk_usage = -1\n            lines = disk_result.stdout.strip().split('\\n')\n            if len(lines) >= 2:\n                parts = lines[1].split()\n                if len(parts) >= 5:\n                    disk_usage = float(parts[4].rstrip('%'))\n            \n            return {\n                'cpu_usage_percent': cpu_usage,\n                'memory_usage_percent': memory_usage,\n                'disk_usage_percent': disk_usage\n            }\n        except Exception:\n            return {\n                'cpu_usage_percent': -1,\n                'memory_usage_percent': -1,\n                'disk_usage_percent': -1\n            }\n    \n    def _check_vpn_status(self) -> str:\n        \"\"\"Check VPN connection status.\"\"\"\n        try:\n            import subprocess\n            result = subprocess.run(\n                ['ipsec', 'status'], capture_output=True, text=True\n            )\n            \n            if result.returncode == 0:\n                if 'ESTABLISHED' in result.stdout:\n                    return 'connected'\n                elif 'CONNECTING' in result.stdout:\n                    return 'connecting'\n                else:\n                    return 'disconnected'\n            return 'unknown'\n        except Exception:\n            return 'unknown'\n    \n    def _test_aws_connectivity(self) -> bool:\n        \"\"\"Test AWS service connectivity.\"\"\"\n        try:\n            self.sqs.get_queue_attributes(\n                QueueUrl=self.config.queue_url,\n                AttributeNames=['QueueArn']\n            )\n            return True\n        except Exception:\n            return False\n    \n    def _measure_network_latency(self) -> float:\n        \"\"\"Measure network latency to AWS services.\"\"\"\n        try:\n            import subprocess\n            result = subprocess.run(\n                ['ping', '-c', '3', f'sqs.{self.config.aws_region}.amazonaws.com'],\n                capture_output=True, text=True\n            )\n            \n            if result.returncode == 0:\n                # Parse ping output for average latency\n                for line in result.stdout.split('\\n'):\n                    if 'avg' in line and 'ms' in line:\n                        # Extract average from ping statistics\n                        parts = line.split('/')\n                        if len(parts) >= 5:\n                            return float(parts[4])\n            return -1\n        except Exception:\n            return -1\n    \n    def collect_all_metrics(self) -> PerformanceMetrics:\n        \"\"\"Collect all performance metrics.\"\"\"\n        self.logger.info(\"Collecting performance metrics...\")\n        \n        # Collect metrics from all sources\n        queue_metrics = self.collect_queue_metrics()\n        processing_metrics = self.collect_processing_metrics()\n        infrastructure_metrics = self.collect_infrastructure_metrics()\n        resource_metrics = self.collect_resource_metrics()\n        network_metrics = self.collect_network_metrics()\n        \n        # Combine into performance metrics object\n        metrics = PerformanceMetrics(\n            timestamp=datetime.utcnow().isoformat(),\n            environment=self.environment,\n            **queue_metrics,\n            **processing_metrics,\n            **infrastructure_metrics,\n            **resource_metrics,\n            **network_metrics\n        )\n        \n        return metrics\n    \n    def analyze_performance(self, metrics: PerformanceMetrics) -> Dict[str, Any]:\n        \"\"\"Analyze performance metrics and provide insights.\"\"\"\n        analysis = {\n            'overall_health': 'healthy',\n            'issues': [],\n            'recommendations': [],\n            'performance_score': 100\n        }\n        \n        # Check for issues\n        if metrics.queue_depth > 100:\n            analysis['issues'].append('High queue depth detected')\n            analysis['recommendations'].append('Consider scaling processing capacity')\n            analysis['performance_score'] -= 20\n        \n        if metrics.error_rate_percent > 10:\n            analysis['issues'].append('High error rate detected')\n            analysis['recommendations'].append('Investigate error causes')\n            analysis['performance_score'] -= 30\n        \n        if metrics.vllm_response_time_ms > 10000:\n            analysis['issues'].append('Slow vLLM response times')\n            analysis['recommendations'].append('Optimize vLLM configuration or hardware')\n            analysis['performance_score'] -= 25\n        \n        if metrics.cpu_usage_percent > 80:\n            analysis['issues'].append('High CPU usage')\n            analysis['recommendations'].append('Monitor CPU-intensive processes')\n            analysis['performance_score'] -= 15\n        \n        if metrics.memory_usage_percent > 85:\n            analysis['issues'].append('High memory usage')\n            analysis['recommendations'].append('Check for memory leaks')\n            analysis['performance_score'] -= 15\n        \n        if metrics.vpn_status != 'connected':\n            analysis['issues'].append('VPN connection issues')\n            analysis['recommendations'].append('Check VPN configuration and connectivity')\n            analysis['performance_score'] -= 40\n        \n        # Determine overall health\n        if analysis['performance_score'] < 60:\n            analysis['overall_health'] = 'critical'\n        elif analysis['performance_score'] < 80:\n            analysis['overall_health'] = 'warning'\n        \n        return analysis\n    \n    def generate_report(self, metrics: PerformanceMetrics, analysis: Dict[str, Any]) -> str:\n        \"\"\"Generate performance report.\"\"\"\n        report = f\"\"\"\n# Air-Gapped RAG Performance Report\n\n**Environment**: {metrics.environment}\n**Timestamp**: {metrics.timestamp}\n**Overall Health**: {analysis['overall_health'].upper()}\n**Performance Score**: {analysis['performance_score']}/100\n\n## Queue Metrics\n- Queue Depth: {metrics.queue_depth}\n- Messages In Flight: {metrics.messages_in_flight}\n- DLQ Depth: {metrics.dlq_depth}\n- Message Age: {metrics.message_age_seconds:.1f}s\n\n## Processing Metrics\n- Processing Rate: {metrics.processing_rate_per_minute:.1f} msg/min\n- Error Rate: {metrics.error_rate_percent:.1f}%\n- Avg Processing Time: {metrics.average_processing_time_ms:.1f}ms\n\n## Infrastructure Metrics\n- vLLM Response Time: {metrics.vllm_response_time_ms:.1f}ms\n- vLLM Availability: {metrics.vllm_availability_percent:.1f}%\n- Worker Uptime: {metrics.worker_uptime_seconds}s\n\n## Resource Metrics\n- CPU Usage: {metrics.cpu_usage_percent:.1f}%\n- Memory Usage: {metrics.memory_usage_percent:.1f}%\n- Disk Usage: {metrics.disk_usage_percent:.1f}%\n\n## Network Metrics\n- VPN Status: {metrics.vpn_status}\n- AWS Connectivity: {'✓' if metrics.aws_connectivity else '✗'}\n- Network Latency: {metrics.network_latency_ms:.1f}ms\n\n## Issues Detected\n\"\"\"\n        \n        if analysis['issues']:\n            for issue in analysis['issues']:\n                report += f\"- ⚠️  {issue}\\n\"\n        else:\n            report += \"- ✅ No issues detected\\n\"\n        \n        report += \"\\n## Recommendations\\n\"\n        \n        if analysis['recommendations']:\n            for rec in analysis['recommendations']:\n                report += f\"- 💡 {rec}\\n\"\n        else:\n            report += \"- ✅ System performing optimally\\n\"\n        \n        return report\n\ndef main():\n    \"\"\"Main entry point.\"\"\"\n    parser = argparse.ArgumentParser(description=\"Air-Gapped RAG Performance Monitor\")\n    parser.add_argument(\n        \"environment\",\n        nargs=\"?\",\n        default=os.getenv(\"ENVIRONMENT\", \"dev\"),\n        choices=[\"dev\", \"staging\", \"prod\"],\n        help=\"Environment to monitor (default: dev)\"\n    )\n    parser.add_argument(\n        \"--output\",\n        choices=[\"json\", \"report\", \"metrics\"],\n        default=\"report\",\n        help=\"Output format (default: report)\"\n    )\n    parser.add_argument(\n        \"--continuous\",\n        action=\"store_true\",\n        help=\"Run continuous monitoring\"\n    )\n    parser.add_argument(\n        \"--interval\",\n        type=int,\n        default=60,\n        help=\"Monitoring interval in seconds (default: 60)\"\n    )\n    \n    args = parser.parse_args()\n    \n    try:\n        monitor = PerformanceMonitor(args.environment)\n        \n        if args.continuous:\n            print(f\"Starting continuous monitoring (interval: {args.interval}s)\")\n            while True:\n                metrics = monitor.collect_all_metrics()\n                analysis = monitor.analyze_performance(metrics)\n                \n                if args.output == \"json\":\n                    output = {\n                        \"metrics\": asdict(metrics),\n                        \"analysis\": analysis\n                    }\n                    print(json.dumps(output, indent=2))\n                elif args.output == \"metrics\":\n                    print(json.dumps(asdict(metrics), indent=2))\n                else:\n                    report = monitor.generate_report(metrics, analysis)\n                    print(report)\n                    print(\"=\" * 50)\n                \n                time.sleep(args.interval)\n        else:\n            # Single run\n            metrics = monitor.collect_all_metrics()\n            analysis = monitor.analyze_performance(metrics)\n            \n            if args.output == \"json\":\n                output = {\n                    \"metrics\": asdict(metrics),\n                    \"analysis\": analysis\n                }\n                print(json.dumps(output, indent=2))\n            elif args.output == \"metrics\":\n                print(json.dumps(asdict(metrics), indent=2))\n            else:\n                report = monitor.generate_report(metrics, analysis)\n                print(report)\n            \n            # Exit with error code if issues detected\n            if analysis['overall_health'] == 'critical':\n                sys.exit(2)\n            elif analysis['overall_health'] == 'warning':\n                sys.exit(1)\n            \n    except KeyboardInterrupt:\n        print(\"\\nMonitoring stopped by user\")\n    except Exception as e:\n        print(f\"Fatal error: {e}\")\n        sys.exit(1)\n\nif __name__ == \"__main__\":\n    main()